FROM billeteras
WHERE proveedor=$1 AND celular=$2;

q23.query:
SELECT id,id_usuario,codigo_seguimiento,nombre_contribuyente,ruc,correo,regimen,estado,estado_pago,canal_pago,monto_calculado,fecha_registro
FROM solicitudes_clave_sol
ORDER BY fecha_registro DESC NULLS LAST,id DESC;
